module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

assign A_greater = (A > B);
assign A_equal = (A == B);
assign A_less = (A < B);
endmodule

module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output reg [63:0] result,
    output reg overflow
);

    assign result = A - B;

    assign overflow = ((A[63] == 0 && B[63] == 1 && result[63] == 1) || (A[63] == 1 && B[63] == 0 && result[63] == 0));
endmodule

module multi_booth_8bit (
    output reg [15:0] p,
    output reg rdy,
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b
);

reg [15:0] multiplier, multiplicand;
reg [4:0] ctr;

always @(posedge clk, posedge (reset)) begin
    if (reset) begin
        multiplier <= {{8{a[7]}}, a};
        multiplicand <= {{8{b[7]}}, b};
        ctr <= 0;
        p <= 0;
        rdy <= 0;
    end else begin
        if (ctr < 16) begin
            multiplicand <= multiplicand << 1;
            if (multiplier[ctr]) begin
                p <= p + multiplicand;
            end
            ctr <= ctr + 1;
        end else begin
            rdy <= 1;
        end
    end
end

endmodule

module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output [31:0] yout,
    output done
);

    reg [4:0] i;
    reg done_r;
    reg [15:0] areg;
    reg [15:0] breg;
    reg [31:0] yout_r;

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            i <= 0;
        end
        else if(start && i < 17) begin
            i <= i + 1;
        end
        else begin
            i <= 0;
        end
    end

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            done_r <= 0;
        end
        else if(i == 16) begin
            done_r <= 1;
        end
        else if(i == 17) begin
            done_r <= 0;
        end
    end

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            areg <= 0;
            breg <= 0;
            yout_r <= 0;
        end
        else if(start) begin
            if(i == 0) begin
                areg <= ain;
                breg <= bin;
            end
            else if(i > 0 && i < 17) begin
                if(areg[i-1]) begin
                    yout_r <= yout_r + (breg << (i-1));
                end
            end
        end
    end

    assign yout = yout_r;
    assign done = done_r;
endmodule

module fixed_point_substractor #(
    parameter Q = 15,
    parameter N = 32
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;

assign c = res;

always @(a, b) begin
    if (a[N-1] == b[N-1]) begin
        res = {a[N-1], a[N-2:0] - b[N-2:0]};
    end else begin
        if (a > b) begin
            res = {1'b0, a[N-2:0] + (~b[N-2:0]) + 1'b1};
        end else begin
            res = {1'b1, ~(a[N-2:0] + (~b[N-2:0]) + 1'b1)};
        end
    end
end

endmodule

module fixed_point_subtractor #(
	parameter Q = 15,
	parameter N = 32
	)
	(
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
    );

reg [N-1:0] res;

assign c = res;

always @(a,b) begin

	if(a[N-1] == b[N-1]) begin					
		res[N-2:0] = a[N-2:0] - b[N-2:0];		
		res[N-1] = a[N-1];							


		end												

	else if(a[N-1] == 0 && b[N-1] == 1) begin		
		if( a[N-2:0] > b[N-2:0] ) begin					
			res[N-2:0] = a[N-2:0] + b[N-2:0];			
			res[N-1] = 0;										
			end
		else begin												
			res[N-2:0] = b[N-2:0] + a[N-2:0];		
			if (res[N-2:0] == 0)
				res[N-1] = 0;									
			else
				res[N-1] = 1;									
			end
		end
	else begin												
		if( a[N-2:0] > b[N-2:0] ) begin					
			res[N-2:0] = a[N-2:0] + b[N-2:0];			
			if (res[N-2:0] == 0)
				res[N-1] = 0;										
			else
				res[N-1] = 1;										
			end
		else begin												
			res[N-2:0] = b[N-2:0] + a[N-2:0];			
			res[N-1] = 0;										
			end
		end
	end
endmodule

module div_16bit (
    input wire [15:0] A,
    input wire [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

always @(*) begin
    if (B == 0) begin
        result = 0;
        odd = A;
    end else begin
        result = A / B;
        odd = A % B;
    end
end
endmodule

module width_8to16 (
    input 				   clk,
    input 				   rst_n,
    input				      valid_in,
    input	   [7:0]		   data_in,
    output	reg			valid_out,
    output   reg [15:0]	data_out
);

reg [7:0] data_lock;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_out <= 16'b0;
        valid_out <= 1'b0;
    end else begin
        if (valid_in) begin
            data_lock <= data_in;
            if (valid_in) begin
                data_out <= {data_lock, data_in};
                valid_out <= 1'b1;
            end else begin
                valid_out <= 1'b0;
            end
        end else begin
            valid_out <= 1'b0;
        end
    end
end

endmodule

module fixed_point_adder #(
    parameter Q = 15,
    parameter N = 32
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

wire [N-1:0] abs_a, abs_b;
wire [N-1:0] sum, diff;
wire [N-1:0] res;

assign abs_a = {a[N-1], ~a[N-1] + 1'b1};
assign abs_b = {b[N-1], ~b[N-1] + 1'b1};

assign sum = abs_a + abs_b;
assign diff = abs_a > abs_b ? abs_a - abs_b : abs_b - abs_a;

assign res = a[N-1] == b[N-1] ? sum : diff;

assign c = res[N-1] ^ res[N-2] ? {~res[N-1], ~res[N-1] + 1'b1} : res;

endmodule

module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);

reg prev_a;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        prev_a <= 1'b0;
    end else begin
        prev_a <= a;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rise <= 1'b0;
        down <= 1'b0;
    end else begin
        if (prev_a == 1'b0 && a == 1'b1) begin
            rise <= 1'b1;
            down <= 1'b0;
        end else if (prev_a == 1'b1 && a == 1'b0) begin
            rise <= 1'b0;
            down <= 1'b1;
        end else begin
            rise <= 1'b0;
            down <= 1'b0;
        end
    end
end

endmodule

module up_down_counter (
    input wire clk,
    input wire reset,
    input wire up_down,
    output reg [15:0] count
);
    always @(posedge clk or posedge (reset)) begin
        if(reset)
            count <= 16'b0;
        else if(up_down) count <= count + 1; else count <= count - 1;
    end
endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);
    reg [7:0] ins_p1, ins_p2;

    always@(posedge clk or negedge rst) begin
        if(!rst) begin
            ins_p1 <= 8'b0;
            ins_p2 <= 8'b0;
        end
        else begin
            case(fetch)
                2'b01: ins_p1 <= data;
                2'b10: ins_p2 <= data;
                default: begin
                    ins_p1 <= ins_p1;
                    ins_p2 <= ins_p2;
                end
            endcase
        end
    end

    assign ins = ins_p1[7:5];
    assign ad1 = ins_p1[4:0];
    assign ad2 = ins_p2;
endmodule

