    assign Co = ((~a & b & Cin) | (a & ~b & Cin) | (a & b & ~Cin) | (a & b & Cin));

endmodule

module counter_12 (
    input rst_n,
    input clk,
    input valid_count,
    output reg [3:0] out
);
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n)
            out <= 4'b0000;
        else if(valid_count==1) begin
            if(out==4'd11) out <= 4'b0000; else out <= out + 1;
        end
    end

endmodule

module calendar (
    input CLK,
    input RST,
    output reg [5:0] Hours,
    output reg [5:0] Mins,
    output reg [5:0] Secs
);

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Secs <= 6'b000000;
    end else if (Secs == 6'b111011) begin
        Secs <= 6'b000000;
    end else begin
        Secs <= Secs + 1;
    end
end

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Mins <= 6'b000000;
    end else if ((Mins == 6'b111011) && (Secs == 6'b111011)) begin
        Mins <= 6'b000000;
    end else if (Secs == 6'b111011) begin
        Mins <= Mins + 1;
    end else begin
        Mins <= Mins;
    end
end

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Hours <= 6'b000000;
    end else if ((Hours == 6'b001011) && (Mins == 6'b111011) && (Secs == 6'b111011)) begin
        Hours <= 6'b000000;
    end else if ((Mins == 6'b111011) && (Secs == 6'b111011)) begin
        Hours <= Hours + 1;
    end else begin
        Hours <= Hours;
    end
end
endmodule

