module CLA_16(A,B,c0,S,px,gx);
    input [16:1] A;
    input [16:1] B;
    input c0;
    output gx,px;
    output [16:1] S;

    wire c4,c8,c12;
    wire Pm1,Gm1,Pm2,Gm2,Pm3,Gm3,Pm4,Gm4;

    adder_4 adder1(
         .x(A[4:1]),
          .y(B[4:1]),
          .c0(c0),
          .c4(),
          .F(S[4:1]),
          .Gm(Gm1),
          .Pm(Pm1)
    );

    adder_4 adder2(
         .x(A[8:5]),
          .y(B[8:5]),
          .c0(c4),
          .c4(),
          .F(S[8:5]),
          .Gm(Gm2),
          .Pm(Pm2)
    );

    adder_4 adder3(
         .x(A[12:9]),
          .y(B[12:9]),
          .c0(c8),
          .c4(),
          .F(S[12:9]),
          .Gm(Gm3),
          .Pm(Pm3)
    );

    adder_4 adder4(
         .x(A[16:13]),
          .y(B[16:13]),
          .c0(c12),
          .c4(),
          .F(S[16:13]),
          .Gm(Gm4),
          .Pm(Pm4)
    );

    assign   c4 = Gm1 ^ (Pm1 & c0),
             c8 = Gm2 ^ (Pm2 & Gm1) ^ (Pm2 & Pm1 & c0),
             c12 = Gm3 ^ (Pm3 & Gm2) ^ (Pm3 & Pm2 & Gm1) ^ (Pm3 & Pm2 & Pm1 & c0);

    assign  px = Pm1 & Pm2 & Pm3 & Pm4,
            gx = Gm4 ^ (Pm4 & Gm3) ^ (Pm4 & Pm3 & Gm2) ^ (Pm4 & Pm3 & Pm2 & Gm1);
endmodule

module adder_4(x,y,c0,c4,F,Gm,Pm);
      input [4:1] x;
      input [4:1] y;
      input c0;
      output c4,Gm,Pm;
      output [4:1] F;

      wire p1,p2,p3,p4,g1,g2,g3,g4;
      wire c1,c2,c3;
      adder adder1(
                 .X(x[1]),
                     .Y(y[1]),
                     .Cin(c0),
                     .F(F[1]),
                     .Cout()
                );

      adder adder2(
                 .X(x[2]),
                     .Y(y[2]),
                     .Cin(c1),
                     .F(F[2]),
                     .Cout()
                );  

      adder adder3(
                 .X(x[3]),
                     .Y(y[3]),
                     .Cin(c2),
                     .F(F[3]),
                     .Cout()
                );

      adder adder4(
                 .X(x[4]),
                     .Y(y[4]),
                     .Cin(c3),
                     .F(F[4]),
                     .Cout()
                );      

        CLA CLA(
            .c0(c0),
            .c1(c1),
            .c2(c2),
            .c3(c3),
            .c4(c4),
            .p1(p1),
            .p2(p2),
            .p3(p3),
            .p4(p4),
            .g1(g1),
            .g2(g2),
            .g3(g3),
            .g4(g4)
        );



  assign   p1 = x[1] ^ y[1],      
           p2 = x[2] ^ y[2],
           p3 = x[3] ^ y[3],
           p4 = x[4] ^ y[4];

  assign   g1 = x[1] & y[1],
           g2 = x[2] & y[2],
           g3 = x[3] & y[3],
           g4 = x[4] & y[4];

  assign Pm = p1 & p2 & p3 & p4,
         Gm = g4 ^ (p4 & g3) ^ (p4 & p3 & g2) ^ (p4 & p3 & p2 & g1);
endmodule

module CLA(c0,c1,c2,c3,c4,p1,p2,p3,p4,g1,g2,g3,g4);

     input c0,g1,g2,g3,g4,p1,p2,p3,p4;
     output c1,c2,c3,c4;

     assign c1 = g1 ^ (p1 & c0),
            c2 = g2 ^ (p2 & g1) ^ (p2 & p1 & c0),
            c3 = g3 ^ (p3 & g2) ^ (p3 & p2 & g1) ^ (p3 & p2 & p1 & c0),
            c4 = g4^(p4&g3)^(p4&p3&g2)^(p4&p3&p2&g1)^(p4&p3&p2&p1&c0);
endmodule

module adder(X,Y,Cin,F,Cout);

  input X,Y,Cin;
  output F,Cout;

  assign F = X ^ Y ^ Cin;
  assign Cout = (X ^ Y) & Cin | X & Y;
endmodule

module signal_generator (
    input clk,
    input rst_n,
    output reg [4:0] wave
);

reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= 2'b00;
        wave <= 5'b0;
    end else begin
        case(state)
            2'b00: begin
                if (wave == 5'b11111) begin
                    state <= 2'b01;
                end else begin
                    wave <= wave + 1;
                end
            end
            2'b01: begin
                if (wave == 5'b00000) begin
                    state <= 2'b00;
                end else begin
                    wave <= wave - 1;
                end
            end
        endcase
    end
end

endmodule

module multi_8bit (
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] product
);
integer i;
reg [7:0] multiplicand;
always@(*) begin
	product = 0;
	multiplicand = A;
	for(i = 0;i < 8 ;i=i+1 ) begin
		if(B[i]==1'b1) begin
			product = product + (multiplicand << i);
		end
	end
end
endmodule

module adder_bcd (
    input  [3:0] A,
    input  [3:0] B,
    input  Cin,
    output [3:0] Sum,
    output Cout
);

wire [4:0] temp_sum;
assign temp_sum = {1'b0, A} + {1'b0, B} + Cin;

wire correction_needed;
assign correction_needed = (temp_sum > 9);

wire [4:0] corrected_sum;
assign corrected_sum = correction_needed ? (temp_sum + 6) : temp_sum;

assign Sum = corrected_sum[3:0];
assign Cout = corrected_sum[4];
endmodule

module square_wave (
    input clk,
    input [7:0] freq,
    output reg wave_out
);
    reg [7:0] count;
    always @(posedge clk) begin
        if(count >= freq - 1) begin
            count <= 0;
            wave_out <= ~wave_out;
        end
        else begin
            count <= count + 1;
        end
    end
endmodule

module traffic_light #(
    parameter idle = 2'd0,
    parameter s1_red = 2'd1,
    parameter s2_yellow = 2'd2,
    parameter s3_green = 2'd3
) (
    input rst_n,
    input clk,
    input pass_request,
    output wire[7:0]clock,
    output reg red,
    output reg yellow,
    output reg green
);


    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end
        else begin
            case(state)
                idle: begin
                    state <= s1_red;
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
                s1_red: begin
                    if(cnt == 3) begin
                        state <= s3_green;
                        p_red <= 0;
                        p_yellow <= 0;
                        p_green <= 1;
                    end
                    else begin
                        state <= s1_red;
                        p_red <= 1;
                        p_yellow <= 0;
                        p_green <= 0;
                    end
                end
                s2_yellow: begin
                    if(cnt == 3) begin
                        state <= s1_red;
                        p_red <= 1;
                        p_yellow <= 0;
                        p_green <= 0;
                    end
                    else begin
                        state <= s2_yellow;
                        p_red <= 0;
                        p_yellow <= 1;
                        p_green <= 0;
                    end
                end
                s3_green: begin
                    if(cnt == 3) begin
                        state <= s2_yellow;
                        p_red <= 0;
                        p_yellow <= 1;
                        p_green <= 0;
                    end
                    else begin
                        state <= s3_green;
                        p_red <= 0;
                        p_yellow <= 0;
                        p_green <= 1;
                    end
                end
            endcase
        end
    end

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            cnt <= 10;
        end
        else begin
            if(pass_request && green && (cnt > 10))
                cnt <= 10;
            else if(!green && p_green)
                cnt <= 60;
            else if(!yellow && p_yellow)
                cnt <= 5;
            else if(!red && p_red) cnt <= 10; else cnt <= cnt - 1;
        end
    end

    assign clock = cnt;

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end
        else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end

endmodule

module parallel2serial (
    input wire clk,
    input wire rst_n,
    input wire [3:0]d,
    output wire valid_out,
    output wire dout
);

reg [3:0] data;
reg [1:0] cnt;
reg valid;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data <= 4'b0;
        cnt <= 2'b0;
        valid <= 1'b0;
    end else begin
        if (cnt == 2'd3) begin
            data <= d;
            cnt <= 2'b0;
            valid <= 1'b1;
        end else begin
            data <= {data[2:0], data[3]};
            cnt <= cnt + 1'b1;
            valid <= 1'b0;
